// Builds the two generated files from the sources in game/:
//   src/core.js      - rules engine + AI for the server
//   public/index.html - the page players open
// Run: node build.mjs
import { readFileSync, writeFileSync, readdirSync, existsSync } from 'node:fs';
const read = f => readFileSync(new URL(f, import.meta.url), 'utf8');

const core = ['game/cards.js', 'game/expansion.js', 'game/engine.js', 'game/ai.js', 'game/replay.js'].map(read).join('\n') + `
function render() {}
function resetUI() {}
function gameState() { return { view: viewFor(0), over: G.over, winner: G.winner, pending: G.pending }; }
export { DEFS, HEROES, DECKS, MANA, RELEASES, CURRENT_RELEASE, replayGame, viewFor, validWire, gameState };
`;
writeFileSync(new URL('src/core.js', import.meta.url), '// GENERATED by build.mjs from game/*.js. Do not edit by hand.\n' + core);

const img = readFileSync(new URL('assets/table.jpg', import.meta.url)).toString('base64');
const css = read('game/style.css').replace('TABLE_IMG', `"data:image/jpeg;base64,${img}"`);
// Card art: drop public/art/<card id>.webp and rebuild; cards without art show a faction placeholder.
const artDir = new URL('public/art/', import.meta.url);
const artIds = existsSync(artDir) ? readdirSync(artDir).filter(f => f.endsWith('.webp')).map(f => f.slice(0, -5)) : [];
const js = `const CARD_ART = new Set(${JSON.stringify(artIds)});\n` + ['game/cards.js', 'game/expansion.js', 'game/engine.js', 'game/replay.js', 'game/client.js', 'game/ui.js'].map(read).join('\n');
writeFileSync(new URL('public/index.html', import.meta.url), `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Ahrivaea</title>
<style>
${css}</style>
</head>
<body>
<div id="app"></div>
<script>
"use strict";
${js}</script>
</body>
</html>
`);
console.log('Built src/core.js and public/index.html');
